interface Mutex { runExclusive<T>(critical: () => Promise<T>): Promise<T>; }

async function bump(mutex: Mutex, key: string): Promise<void> {
  await mutex.runExclusive(async () => {              // acquire on entry
    await store.set(key, (await store.get(key)) + 1);
  });                                                 // released on every exit path
}
